class Solution:
    def maximumLength(self, s: str) -> int:
        from collections import defaultdict
        count = defaultdict(int)
        i = 0
        n = len(s)
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            run = j - i
            for L in range(1, run + 1):
                count[(s[i], L)] += run - L + 1
            i = j
        ans = -1
        for (c, L), v in count.items():
            if v >= 3:
                ans = max(ans, L)
        return ans
